            print('REPEATABILITY URL SAMPLES',uris[:10])
        elif i in [4,5]:
            print('LINKS',uris)
        for name in p.get('/Resources',{}).get('/XObject',{}):
            x=p['/Resources']['/XObject'][name].get_object()
